using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
[InitializeOnLoad] public static class LayoutPlayChecks {
 const string Running="ShiokaLayoutSmokeRunning";static LayoutSmokeInput logical;static TrainingFighter player;static float start,x;static bool moved,air,attack;static int frames;static double began;static string report;
 static LayoutPlayChecks(){if(SessionState.GetBool(Running,false))EditorApplication.update+=Tick;}
 public static void Start(){if(EditorApplication.isPlaying)throw new Exception("Start only in fresh batch edit mode");EditorSceneManager.OpenScene("Assets/Shioka/Scenes/CombatFormulaComparison.unity");SessionState.SetBool(Running,true);EditorApplication.update-=Tick;EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Tick(){try{if(!EditorApplication.isPlaying)return;if(logical==null){player=UnityEngine.Object.FindObjectsByType<TrainingFighter>(FindObjectsSortMode.None).First(f=>f.GetComponent<TrainingControls>()!=null);logical=player.gameObject.AddComponent<LayoutSmokeInput>();player.SetInputSource(logical);start=Time.fixedTime;logical.start=start;x=player.transform.position.x;began=EditorApplication.timeSinceStartup;var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-layoutReport");report=i>=0?args[i+1]:"Temp/layout-play.txt";}
 float t=Time.fixedTime-start;frames++;moved|=Mathf.Abs(player.transform.position.x-x)>.05f;air|=player.CurrentPhase==TrainingFighter.Phase.Air;attack|=player.CurrentPhase==TrainingFighter.Phase.Attack;if(t>3.2f){bool sprites=UnityEngine.Object.FindObjectsByType<ArmoredStaticPoseView>(FindObjectsSortMode.None).All(v=>v.image!=null&&v.image.sprite!=null);bool landed=player.IsGrounded;bool good=moved&&air&&attack&&sprites&&landed;File.WriteAllText(report,$"movement={moved}\njump={air}\nattack={attack}\nlanded={landed}\nsprites={sprites}\nrenderUpdates={frames}\nfixedElapsed={t}\nScripted logical input through existing ITrainingInputSource; batch virtual keyboard did not arrive. Physical keyboard unverified.\n");Finish(good?0:2);}else if(EditorApplication.timeSinceStartup-began>90)throw new Exception("Simulation did not progress within bounded timeout");}catch(Exception e){Debug.LogException(e);if(!string.IsNullOrEmpty(report))File.WriteAllText(report,e.ToString());Finish(3);}}
 static void Finish(int code){SessionState.SetBool(Running,false);EditorApplication.update-=Tick;EditorApplication.Exit(code);}
}

public sealed class LayoutSmokeInput:MonoBehaviour,ITrainingInputSource {public float start;bool jumped,punched;public TrainingInputFrame ReadInput(){float t=Time.fixedTime-start;var f=new TrainingInputFrame{Movement=t>=.25f&&t<.55f?Vector2.right:Vector2.zero,Commands=new TrainingCommand[0]};if(t>=.55f&&!jumped){jumped=true;f.Commands=new[]{TrainingCommand.Jump};}else if(t>=1.95f&&!punched){punched=true;f.Commands=new[]{TrainingCommand.Light};}return f;}}
